import { useCallback, useState } from 'react';
import {
  Badge,
  Card,
  Divider,
  FormField,
  Heading,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  fontFamily: FontFamily;
}

export interface AppearanceSettingsScreenProps {
  value?: Partial<AppearanceSettings>;
  onChange?: (next: AppearanceSettings) => void;
}

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'system',
};

const THEME_OPTIONS: { value: ThemeMode; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const SCALE_MIN = 80;
const SCALE_MAX = 140;

export default function AppearanceSettingsScreen({
  value,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...DEFAULTS,
    ...value,
  });

  const update = useCallback(
    <K extends keyof AppearanceSettings>(key: K, next: AppearanceSettings[K]) => {
      setSettings((prev) => {
        const merged = { ...prev, [key]: next };
        onChange?.(merged);
        return merged;
      });
    },
    [onChange],
  );

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === settings.theme)?.label ?? '';

  return (
    <Card className="jx-card" style={{ maxWidth: 'var(--jx-size-container-sm)' }}>
      <Stack direction="column" gap="lg">
        <Stack direction="row" align="center" justify="space-between" gap="md">
          <Heading level={2}>Внешний вид</Heading>
          <Badge variant="neutral">{themeLabel}</Badge>
        </Stack>

        <FormField label="Тема" htmlFor="appearance-theme">
          <SegmentedControl
            id="appearance-theme"
            value={settings.theme}
            options={THEME_OPTIONS}
            onChange={(next: ThemeMode) => update('theme', next)}
            fullWidth
          />
        </FormField>

        <FormField label="Масштаб интерфейса" htmlFor="appearance-scale">
          <Stack direction="row" align="center" gap="md">
            <Slider
              id="appearance-scale"
              min={SCALE_MIN}
              max={SCALE_MAX}
              step={5}
              value={settings.scale}
              onChange={(next: number) => update('scale', next)}
              style={{ flex: 1 }}
            />
            <Text
              variant="body"
              style={{
                minWidth: 'var(--jx-size-8)',
                textAlign: 'right',
                color: 'var(--jx-color-text-muted)',
                fontVariantNumeric: 'tabular-nums',
              }}
            >
              {settings.scale}%
            </Text>
          </Stack>
        </FormField>

        <Switch
          checked={settings.dense}
          onChange={(next: boolean) => update('dense', next)}
          label="Плотная вёрстка"
          description="Уменьшает отступы между элементами интерфейса"
        />

        <Divider />

        <Stack direction="column" gap="md">
          <Text variant="subtitle" style={{ color: 'var(--jx-color-text-muted)' }}>
            Ещё
          </Text>

          <FormField label="Шрифт" htmlFor="appearance-font">
            <Select
              id="appearance-font"
              value={settings.fontFamily}
              options={FONT_OPTIONS}
              onChange={(next: FontFamily) => update('fontFamily', next)}
            />
          </FormField>
        </Stack>
      </Stack>
    </Card>
  );
}

